JS = '/* 「本段累計場內資金」顯示（純顯示，不改任何數據）\n   - 數據：#liq-data（魔方貼文「流動性概況」的各幣場內資金，億美元；由 mag admin 每日寫入）\n   - 累計：每個標的按自己的進／退場期分段，階段反轉即歸零重新累計\n   - 當日貼文沒有該幣數據：沿用前值，字色變淡 */\n(function(){\n  var src=document.getElementById(\'liq-data\'); if(!src) return;\n  var L; try{L=JSON.parse(src.textContent);}catch(e){return;}\n  var css=document.createElement(\'style\');\n  css.textContent=\'.lq{font-size:8px;line-height:1.2;font-weight:700;letter-spacing:0.1px;white-space:nowrap}\'+\n    \'.lq.p{color:#34d399}.lq.n{color:#f87171}.lq.z{color:#a3a3a3}.lq.na{opacity:.45}\';\n  document.head.appendChild(css);\n  var RE=/^(\\d{4}-\\d{2}-\\d{2}) [^:]+: [^,]*,[^,]*, (進|退)場期D(\\d+)/;\n  function fmt(v){var s=(Math.round(v*10)/10).toFixed(1).replace(/\\.0$/,\'\');if(s===\'-0\')s=\'0\';return (v>0&&s!==\'0\'?\'+\':\'\')+s;}\n  function run(){\n    document.querySelectorAll(\'.lq\').forEach(function(e){e.remove();});\n    var coins={};\n    Object.keys(L).forEach(function(d){var c=(L[d]||{}).coins||{};Object.keys(c).forEach(function(k){coins[k.toUpperCase()]=1;});});\n    var rows={};\n    document.querySelectorAll(\'#T tbody tr[id^="row_"]\').forEach(function(tr){rows[tr.id.replace(/^row_[^_]+_/,\'\').toUpperCase()]=tr;});\n    Object.keys(coins).forEach(function(name){\n      var tr=rows[name]; if(!tr) return;\n      var prevPh=null,prevD=0,cum=0,n=0,from=null;\n      [].forEach.call(tr.cells,function(td){\n        var m=RE.exec(td.getAttribute(\'title\')||\'\'); if(!m) return;\n        var date=m[1],ph=m[2],d=+m[3];\n        if(ph!==prevPh||d<=prevD){cum=0;n=0;from=null;}\n        prevPh=ph;prevD=d;\n        var day=L[date],v=null;\n        if(day&&day.coins){Object.keys(day.coins).forEach(function(k){if(k.toUpperCase()===name)v=+day.coins[k];});}\n        if(v!==null&&!isNaN(v)){cum+=v;n++;if(!from)from=date;}\n        if(!n) return;\n        var el=document.createElement(\'div\'),r=Math.round(cum*10)/10;\n        el.className=\'lq \'+(r>0?\'p\':(r<0?\'n\':\'z\'))+(v===null?\' na\':\'\');\n        el.textContent=\'Σ\'+fmt(cum);\n        el.title=\'本段（\'+ph+\'場期）累計場內資金 \'+fmt(cum)+\' 億美元｜自 \'+from+\' 起 \'+n+\' 日有數據｜當日 \'+(v===null?\'貼文無數據\':fmt(v));\n        var jl=td.querySelector(\'.jl\'); if(jl) td.insertBefore(el,jl); else td.appendChild(el);\n      });\n    });\n  }\n  run();\n  window.liqRun=run;\n})();\n'
FN = '// ── 2026-10-08：把當日「流動性概況」併入 index.html 的 #liq-data（純顯示用；網站據此計本段累計）──\nfunction putLiqData(h, dt, liq) {\n  try {\n    if (!liq) return h;\n    const open = \'<script id="liq-data" type="application/json">\';\n    const a = h.indexOf(open); if (a === -1) return h;\n    const b = h.indexOf(\'</\' + \'script>\', a); if (b === -1) return h;\n    const obj = JSON.parse(h.slice(a + open.length, b));\n    obj[dt] = { coins: liq.coins, net: liq.net, inner: liq.inner, outer: liq.outer, dir: liq.dir };\n    const sorted = {}; Object.keys(obj).sort().forEach(k => sorted[k] = obj[k]);\n    return h.slice(0, a + open.length) + JSON.stringify(sorted).replace(/</g, \'\\\\u003c\') + h.slice(b);\n  } catch (e) { return h; }\n}\n\n'
OPEN = '<script id="liq-data" type="application/json">'
def dump(o): return json.dumps(dict(sorted(o.items())), ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
def patch_index():
    h = open('index.html', encoding='utf-8').read(); n0 = h.count('<td')
    if OPEN in h:
        a = h.index(OPEN) + len(OPEN); b = h.index('</script>', a); cur = json.loads(h[a:b])
        add = [d for d in SEED if d not in cur]
        for d in add: cur[d] = SEED[d]
        h = h[:a] + dump(cur) + h[b:]
        a2 = h.index('<script id="liqcum">'); b2 = h.index('</script>', a2) + 9
        h = h[:a2] + '<script id="liqcum">\n' + JS + '</script>' + h[b2:]
        msg = 'index.html：liq-data 已有，併入 %d 日（共 %d 日），顯示腳本已更新' % (len(add), len(cur))
    else:
        assert h.count('</body>') == 1, '找不到唯一的 </body>'
        h = h.replace('</body>', OPEN + dump(SEED) + '</script>\n<script id="liqcum">\n' + JS + '</script>\n</body>')
        msg = 'index.html：已加入 liq-data（%d 日）與 liqcum 顯示腳本' % len(SEED)
    assert h.count('<td') == n0
    open('index.html', 'w', encoding='utf-8').write(h); print(msg)
def patch_admin():
    h = open('mag_admin.html', encoding='utf-8').read()
    if 'function putLiqData' in h: print('mag_admin.html：已有 putLiqData，跳過'); return
    reps = [('function buildNewHtml() {', FN + 'function buildNewHtml() {'),
            ("""  h = h.slice(0, trEnd) + `\\n        <th class="today" title="${date}">${label}</th>` + h.slice(trEnd);
  return h;
}""", """  h = h.slice(0, trEnd) + `\\n        <th class="today" title="${date}">${label}</th>` + h.slice(trEnd);
  return putLiqData(h, date, LIQ);
}""")]
    for a, b in reps:
        if h.count(a) != 1: sys.exit('mag_admin.html 結構不符，未修改：' + a[:60])
    for a, b in reps: h = h.replace(a, b)
    open('mag_admin.html', 'w', encoding='utf-8').write(h); print('mag_admin.html：寫入時會把當日流動性概況併入 liq-data')
patch_index(); patch_admin()
